from flask import Flask, request

app = Flask(__name__)

@app.route('/list')
def list_names():
    items = request.args.get('items')

    names_html = f'''
    <h1>Your Names</h1>
    {items}
    '''

    return names_html

if __name__ == '__main__':
    app.run()

